    int cols[4] = {2 * c, 2 * c + 1, 2 * c, 2 * c + 1};
    for (int i = 0; i < 4; i++) {
        double s1 = 0, s2 = 0;
        for (int k = 0; k < 16; k++) {
            s1 += (double)(float)A[rows[i]][k] * (double)(float)B[k][cols[i]];
            s2 += (double)(float)A[rows[i]][k] * (double)(float)B[k][cols[i]];
        }
        ref1[i] = (float)s1; ref2[i] = (float)s2;
    }
