__global__ void __launch_bounds__(NUM_THREADS, 2) attention_fwd_kernel(
    const __nv_bfloat16* __restrict__ q,
    const __nv_bfloat16* __restrict__ k,
    const __nv_bfloat16* __restrict__ v,
    __nv_bfloat16* __restrict__ out,
    int seq_len, float scale_log2, bool causal, int q_per_kv)
{
    extern __shared__ char smem_raw[];
    __nv_bfloat16* sQ = reinterpret_cast<__nv_bfloat16*>(smem_raw);
    __nv_bfloat16* sK = sQ + BLOCK_M * HEAD_DIM;
    __nv_bfloat16* sV = sK + BLOCK_N * HEAD_DIM;
    // swizzled addresses: unit u of row r at byte row*256 + ((u+r)&15)*16

    const int m_tile = blockIdx.x;
    const int bh = blockIdx.y;
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int g = lane / 4;      // row within warp's 16-row group (0..7)
    const int c = lane % 4;      // column-pair index (0..3)

    const long long base = (long long)bh * seq_len * HEAD_DIM;
    const long long base_kv = (long long)(bh / q_per_kv) * seq_len * HEAD_DIM;

    // ---- load Q tile (BLOCK_M x HEAD_DIM) into shared ----
    {
        const int nvec = BLOCK_M * HEAD_DIM / 8;  // 1024 16B units
#pragma unroll
        for (int i = 0; i < nvec / NUM_THREADS; ++i) {
            const int idx = i * NUM_THREADS + threadIdx.x;
            const int row = idx / 16, u = idx % 16;
            const int grow = m_tile * BLOCK_M + row;
            if (grow < seq_len) {
                cp_async16(swz16(sQ, row, u),
                           q + base + (long long)grow * HEAD_DIM + u * 8);
            }
        }
        asm volatile("cp.async.commit_group;\n");
        asm volatile("cp.async.wait_group 0;\n");
        __syncthreads();
    }

    // ---- Q A-fragments into registers: q[8][4] (k-chunks) ----
    uint32_t qr[8][4];
#pragma unroll
    for (int k = 0; k < 8; ++k)
        ldm_x4(qr[k], sQ, warp * ROWS_PER_WARP, 2 * k);

    float acc[16][4];
    float m2_g = -INFINITY, m2_g8 = -INFINITY;
    float l_g = 0.f, l_g8 = 0.f;
#pragma unroll
    for (int i = 0; i < 16; ++i)
#pragma unroll
        for (int j = 0; j < 4; ++j) acc[i][j] = 0.f;

    const int row_hi = min(m_tile * BLOCK_M + BLOCK_M - 1, seq_len - 1);
    int n_tiles = (seq_len + BLOCK_N - 1) / BLOCK_N;
    if (causal) n_tiles = min(n_tiles, row_hi / BLOCK_N + 1);
    const bool is_diag_tile = causal;  // per-block: last tile is the diagonal

    for (int nt = 0; nt < n_tiles; ++nt) {
        // ---- zero out-of-range K/V rows (only affects last tile) ----
        const int kv_start = nt * BLOCK_N;
        if (kv_start + BLOCK_N > seq_len) {
            const int z0 = max(kv_start, seq_len) - kv_start;
#pragma unroll
            for (int r = z0; r < BLOCK_N; ++r)
#pragma unroll
                for (int u = 0; u < 16; ++u)
                    *(uint4*)(uintptr_t)swz16(sK, r, u) = make_uint4(0, 0, 0, 0);
#pragma unroll
            for (int r = z0; r < BLOCK_N; ++r)
#pragma unroll
                for (int u = 0; u < 16; ++u)
                    *(uint4*)(uintptr_t)swz16(sV, r, u) = make_uint4(0, 0, 0, 0);
        }
        // ---- cp.async K/V tile ----
        {
            const int nvec = BLOCK_N * HEAD_DIM / 8;  // 1024 units
#pragma unroll
            for (int i = 0; i < nvec / NUM_THREADS; ++i) {
                const int idx = i * NUM_THREADS + threadIdx.x;
                const int row = idx / 16, u = idx % 16;
                const int grow = kv_start + row;
                if (grow < seq_len) {
                    const long long off = (long long)grow * HEAD_DIM + u * 8;
                    cp_async16(swz16(sK, row, u), k + base_kv + off);
                    cp_async16(swz16(sV, row, u), v + base_kv + off);
                }
            }
            asm volatile("cp.async.commit_group;\n");
            asm volatile("cp.async.wait_group 0;\n");
            __syncthreads();
        }

        // ---- QK^T ----
        float S[8][4];
#pragma unroll
        for (int n = 0; n < 8; ++n)
#pragma unroll
            for (int j = 0; j < 4; ++j) S[n][j] = 0.f;
#pragma unroll
        for (int n = 0; n < 8; ++n) {
#pragma unroll
            for (int k2 = 0; k2 < 4; ++k2) {
                uint32_t b[4];
                ldm_x4t(b, sK, kv_start + n * 8, 4 * k2);
                mma_16816(S[n], qr[2 * k2],     b + 0);
                mma_16816(S[n], qr[2 * k2 + 1], b + 2);
            }
        }

        // ---- causal mask on the diagonal tile ----
        if (is_diag_tile && nt == m_tile) {
            const int row0 = m_tile * BLOCK_M;
#pragma unroll
            for (int n = 0; n < 8; ++n) {
                const int col0 = nt * BLOCK_N + n * 8 + 2 * c;
                if (col0 > row0 + g)              S[n][0] = -INFINITY;
                if (col0 + 1 > row0 + g)          S[n][1] = -INFINITY;
                if (col0 > row0 + g + 8)          S[n][2] = -INFINITY;
                if (col0 + 1 > row0 + g + 8)      S[n][3] = -INFINITY;
            }
        }

        // ---- softmax (rows g and g+8), log2 domain ----
        float m_g = -INFINITY, m_g8 = -INFINITY;
#pragma unroll
        for (int n = 0; n < 8; ++n) {
            m_g  = fmaxf(m_g,  fmaxf(S[n][0], S[n][1]));
            m_g8 = fmaxf(m_g8, fmaxf(S[n][2], S[n][3]));
        }
        m_g = reduce4_max(m_g);   m_g8 = reduce4_max(m_g8);
        const float m2n_g  = m_g  * scale_log2;
        const float m2n_g8 = m_g8 * scale_log2;
        const float corr_g  = exp2f(m2_g  - m2n_g);
        const float corr_g8 = exp2f(m2_g8 - m2n_g8);
        // rescale running accumulators
        float lsum_g = 0.f, lsum_g8 = 0.f;
#pragma unroll
        for (int i = 0; i < 16; ++i) {
            acc[i][0] *= corr_g;  acc[i][1] *= corr_g;
            acc[i][2] *= corr_g8; acc[i][3] *= corr_g8;
        }
        l_g  = l_g  * corr_g;
        l_g8 = l_g8 * corr_g8;

        // P = exp2(S*scale - m2), packed bf16 for PV mma
        uint32_t P[8][2];
#pragma unroll
        for (int n = 0; n < 8; ++n) {
            const float p0 = exp2f(S[n][0] * scale_log2 - m2n_g);
            const float p1 = exp2f(S[n][1] * scale_log2 - m2n_g);
            const float p2 = exp2f(S[n][2] * scale_log2 - m2n_g8);
            const float p3 = exp2f(S[n][3] * scale_log2 - m2n_g8);
            P[n][0] = pack2f(p0, p1);
            P[n][1] = pack2f(p2, p3);
            lsum_g  += p0 + p1;
            lsum_g8 += p2 + p3;
        }
        l_g  += reduce4_sum(lsum_g);
        l_g8 += reduce4_sum(lsum_g8);
        m2_g = m2n_g;  m2_g8 = m2n_g8;

        // ---- PV: O += P x V ----
#pragma unroll
        for (int j = 0; j < 8; ++j) {
            // A fragment: rows g,g+8 x cols 2c,2c+1 within each 16-col k-group
            uint32_t a[4] = {P[2 * j][0], P[2 * j + 1][0],
                             P[2 * j][1], P[2 * j + 1][1]};
#pragma unroll
            for (int i = 0; i < 8; ++i) {
                uint32_t b[4];
                ldm_x4t(b, sV, kv_start + j * 16, 2 * i);
                mma_16816(acc[2 * i],     a, b + 0);
                mma_16816(acc[2 * i + 1], a, b + 2);
            }
        }
        __syncthreads();  // before next tile's cp.async overwrites sK/sV
    }

    // ---- epilogue: normalize and store ----
    const float inv_g  = l_g  > 0.f ? 1.f / l_g  : 0.f;
    const float inv_g8 = l_g8 > 0.f ? 1.f / l_g8 : 0.f;
#pragma unroll
    for (int i = 0; i < 16; ++i) {
        acc[i][0] *= inv_g;  acc[i][1] *= inv_g;
        acc[i][2] *= inv_g8; acc[i][3] *= inv_g8;
    }
    // write O to shared (reuse sQ buffer), swizzled layout
#pragma unroll
    for (int i = 0; i < 16; ++i) {
        const int col = i * 8 + 2 * c;
        const int r0 = warp * ROWS_PER_WARP + g;
        const int r1 = r0 + 8;
        *(uint32_t*)(uintptr_t)swz16(sQ, r0, i) = pack2f(acc[i][0], acc[i][1]);
        *(uint32_t*)(uintptr_t)swz16(sQ, r1, i) = pack2f(acc[i][2], acc[i][3]);
    }
    __syncthreads();
    {
        const int nvec = BLOCK_M * HEAD_DIM / 8;
#pragma unroll
        for (int i = 0; i < nvec / NUM_THREADS; ++i) {
            const int idx = i * NUM_THREADS + threadIdx.x;
            const int row = idx / 16, u = idx % 16;
            const int grow = m_tile * BLOCK_M + row;
            if (grow < seq_len) {
                uint4 val = *(uint4*)(uintptr_t)swz16(sQ, row, u);
                *(uint4*)(out + base + (long long)grow * HEAD_DIM + u * 8) = val;
            }
        }
    }
}

}  // end part-1 helpers

__global__ void __launch_bounds__(NUM_THREADS, 2) attention_fwd_kernel(
    const __nv_bfloat16* __restrict__ q,
    const __nv_bfloat16* __restrict__ k,
    const __nv_bfloat16* __restrict__ v,
    __nv_bfloat16* __restrict__ out,
