    float m2_g = -INFINITY, m2_g8 = -INFINITY;
    float l_g = 0.f, l_g8 = 0.f;
#pragma unroll
    for (int i = 0; i < 16; ++i)
#pragma unroll
        for (int j = 0; j < 4; ++j) acc[i][j] = 0.f;

    const int row_hi = min(m_tile * BLOCK_M + BLOCK_M - 1, seq_len - 1);
    int n_tiles = (seq_len + BLOCK_N - 1) / BLOCK_N;
    if (causal) n_tiles = min(n_tiles, row_hi / BLOCK_N + 1);
    const bool is_diag_tile = causal;  // per-block: last tile is the diagonal

