#pragma unroll
            for (int r = z0; r < BLOCK_N; ++r)
#pragma unroll
                for (int u = 0; u < 16; ++u)
                    *(uint4*)(uintptr_t)swz16(sK, r, u) = make_uint4(0, 0, 0, 0);
#pragma unroll
            for (int r = z0; r < BLOCK_N; ++r)
#pragma unroll
                for (int u = 0; u < 16; ++u)
                    *(uint4*)(uintptr_t)swz16(sV, r, u) = make_uint4(0, 0, 0, 0);
        }
        // ---- cp.async K/V tile ----
        {
            const int nvec = BLOCK_N * HEAD_DIM / 8;  // 1024 units
#pragma unroll
            for (int i = 0; i < nvec / NUM_THREADS; ++i) {
                const int idx = i * NUM_THREADS + threadIdx.x;
