// XOR-swizzled 16B-unit address. Layout: row stride 256 B (128 bf16);
// 16B unit u (0..15) of row r lives at slot ((u + r + (r>>3)) & 15) within
// the row. The (r>>3) term shifts bank phase by one 16B slot between every
// 8-row group, so ldmatrix x2/x4 reads of 16 consecutive rows are
// conflict-free (each 8-row matrix group uses distinct banks).
__device__ __forceinline__ uint32_t swz16(const void* base, int row, int u) {
    uint32_t b = (uint32_t)__cvta_generic_to_shared(base);
    return b + row * 256 + (((u + row + (row >> 3)) & 15) * 16);
}

